INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('ee9202208adfae7d1f0d','Amedex 2023.pdf','605','Mixed/Unclassified','A 32-year-old African male presents to the Emergency Department with fatigue, jaundice, dark-colored urine and acute decrease in hemoglobin for the past four days. Liver function tests are normal, except for an elevated unconjugated bilirubin level.
Which one of the laboratory results would be most consistent with the diagnosis of hemolysis due to glucose-6-phosphate dehydrogenase deficiency?','{"A":"Spherocytosis.","B":"Schistocytosis.","C":"Positive Coomb’s test.","D":"Heinz bodies.","E":"Elliptocytosis."}','D','Glucose-6-phosphate dehydrogenase (G6PD) deficiency is the most common enzyme deficiency in human, affecting 400 million people worldwide, with a high prevalence in people of African, Asian, and Mediterranean descent. The condition is
inherited as an X-linked recessive disorder. It is polymorphic with more than 300 variants.
G6PD deficiency can present as neonatal hyperbilirubinemia. People with this disorder can experience episodes of brisk hemolysis in response to oxidative stresses or, less commonly, have chronic hemolysis. However, many individuals with G6PD
deficiency are asymptomatic. G6PD deficiency confers partial protection against malaria.
The diagnosis of G6PD deficiency can be made on the basis of a well-documented history, evidence of hemolysis, a peripheral-blood smear showing Heinz bodies (erythrocytes with denatured hemoglobin) and ‘bite cells’. Measurement of G6PD
activity while the patient is in remission is the gold-standard diagnostic test for G6PD deficiency.
G6PD deficiency should be suspected in all patients with non-immune acute hemolysis and no spherocytosis on laboratory testing.
(Option A) Spherocytes are characteristic feature in hereditary spherocytosis.
(Option B) Schistocytes are seen in microangiopathic hemolytic anemia (MAHA) associated with hemolytic uremic syndrome and thrombotic thrombocytopenic purpura (TTP). 
(Option C) Positive Coombs test is the characteristic feature of immune-mediates hemolytic anemia.
(Option E) Elliptocytosis, also known and ovalocytosis, is a feature of hereditary elliptocytosis – an inherited disorder in which an abnormally large number of patient’s red blood cells are elliptical rather than the typical biconcave disc-shaped.','{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","supporting_pages":[],"source_qid":"799","duplicate_group_id":"exact-6ec65ea69184","duplicate_sources":[{"record_id":"ee9202208adfae7d1f0d","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":605,"source_qid":"799"}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"strict_ocr_tolerant","text_method":"native","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','low','{"record_id":"ee9202208adfae7d1f0d","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_year":2023,"source_page":605,"source_qid":"799","domain_hint":"Mixed/Unclassified","stem":"A 32-year-old African male presents to the Emergency Department with fatigue, jaundice, dark-colored urine and acute decrease in hemoglobin for the past four days. Liver function tests are normal, except for an elevated unconjugated bilirubin level.\nWhich one of the laboratory results would be most consistent with the diagnosis of hemolysis due to glucose-6-phosphate dehydrogenase deficiency?","options":{"A":"Spherocytosis.","B":"Schistocytosis.","C":"Positive Coomb’s test.","D":"Heinz bodies.","E":"Elliptocytosis."},"source_answer":"D","source_explanation":"Glucose-6-phosphate dehydrogenase (G6PD) deficiency is the most common enzyme deficiency in human, affecting 400 million people worldwide, with a high prevalence in people of African, Asian, and Mediterranean descent. The condition is\ninherited as an X-linked recessive disorder. It is polymorphic with more than 300 variants.\nG6PD deficiency can present as neonatal hyperbilirubinemia. People with this disorder can experience episodes of brisk hemolysis in response to oxidative stresses or, less commonly, have chronic hemolysis. However, many individuals with G6PD\ndeficiency are asymptomatic. G6PD deficiency confers partial protection against malaria.\nThe diagnosis of G6PD deficiency can be made on the basis of a well-documented history, evidence of hemolysis, a peripheral-blood smear showing Heinz bodies (erythrocytes with denatured hemoglobin) and ‘bite cells’. Measurement of G6PD\nactivity while the patient is in remission is the gold-standard diagnostic test for G6PD deficiency.\nG6PD deficiency should be suspected in all patients with non-immune acute hemolysis and no spherocytosis on laboratory testing.\n(Option A) Spherocytes are characteristic feature in hereditary spherocytosis.\n(Option B) Schistocytes are seen in microangiopathic hemolytic anemia (MAHA) associated with hemolytic uremic syndrome and thrombotic thrombocytopenic purpura (TTP). \n(Option C) Positive Coombs test is the characteristic feature of immune-mediates hemolytic anemia.\n(Option E) Elliptocytosis, also known and ovalocytosis, is a feature of hereditary elliptocytosis – an inherited disorder in which an abnormally large number of patient’s red blood cells are elliptical rather than the typical biconcave disc-shaped.","source_answer_status":"present","current_answer":null,"current_answer_status":"needs_verification","current_evidence":[],"currentness_risk":"low","currentness_keywords":[],"likely_visual_question":false,"parser_confidence":"very_high","parser_mode":"strict_ocr_tolerant","text_method":"native","parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","stem_hash":"6ec65ea6918407483cc71ea8c4d8455c02ff23ce","duplicate_group_id":"exact-6ec65ea69184","duplicate_sources":[{"record_id":"ee9202208adfae7d1f0d","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":605,"source_qid":"799"}]}',1,'v2.9.4','2026-09-24T00:00:00.000Z') ON CONFLICT(record_id) DO UPDATE SET source_file=excluded.source_file,source_page=excluded.source_page,domain=excluded.domain,stem=excluded.stem,options_json=excluded.options_json,source_answer=excluded.source_answer,source_explanation=excluded.source_explanation,provenance_json=excluded.provenance_json,visual_asset=excluded.visual_asset,visual_url=excluded.visual_url,options_mode=excluded.options_mode,current_answer=excluded.current_answer,current_answer_status=excluded.current_answer_status,current_evidence_json=excluded.current_evidence_json,currentness_risk=excluded.currentness_risk,record_json=excluded.record_json,active_quiz=excluded.active_quiz,import_version=excluded.import_version,imported_at=excluded.imported_at;
