INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('462a2f27b3586aa5b558','Amedex 2023.pdf','621','Mixed/Unclassified','A 55-year-old man has been on warfarin for AF for the past 3 months. He presented with an incarcerated inguinal hernia and was booked for emergent surgery. Warfarin was stopped and fresh frozen plasma was given. Which one of the following is
the time to resume warfarin therapy?','{"A":"12 hours post-op.","B":"48 hours post-op.","C":"Immediately after recovery from anesthesia.","D":"5 days post-op.","E":"When INR is less than 1.8 again."}','A','For those, whose warfarin therapy has been stopped before major surgical procedures, it is recommended that the previous maintenance dose of warfarin be resumed on the night of surgery (12-24 hours). In addition to warfarin, low molecular
weight heparin (LMWH) in prophylactic dose or unfractionated heparin (UFH) with slow infusion is started at the same time. The target APTT is 1.5 times the normal.
LMWH or UFH is continued for at least 5 days and is ceased 48 after the target INR is reached (≥1.8).','{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","supporting_pages":[],"source_qid":"1062","duplicate_group_id":"exact-e5c3bb78c545","duplicate_sources":[{"record_id":"462a2f27b3586aa5b558","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":621,"source_qid":"1062"}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"strict_ocr_tolerant","text_method":"native","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','high','{"record_id":"462a2f27b3586aa5b558","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_year":2023,"source_page":621,"source_qid":"1062","domain_hint":"Mixed/Unclassified","stem":"A 55-year-old man has been on warfarin for AF for the past 3 months. He presented with an incarcerated inguinal hernia and was booked for emergent surgery. Warfarin was stopped and fresh frozen plasma was given. Which one of the following is\nthe time to resume warfarin therapy?","options":{"A":"12 hours post-op.","B":"48 hours post-op.","C":"Immediately after recovery from anesthesia.","D":"5 days post-op.","E":"When INR is less than 1.8 again."},"source_answer":"A","source_explanation":"For those, whose warfarin therapy has been stopped before major surgical procedures, it is recommended that the previous maintenance dose of warfarin be resumed on the night of surgery (12-24 hours). In addition to warfarin, low molecular\nweight heparin (LMWH) in prophylactic dose or unfractionated heparin (UFH) with slow infusion is started at the same time. The target APTT is 1.5 times the normal.\nLMWH or UFH is continued for at least 5 days and is ceased 48 after the target INR is reached (≥1.8).","source_answer_status":"present","current_