INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('d4a58b6359fbd2cd0cc0','Amedex 2023.pdf','622','Mixed/Unclassified','A 65-year-old woman underwent an emergency surgery for a strangulated femoral hernia 2 days ago. She was on warfarin that was ceased before the surgery and fresh frozen plasma was given. Which one of the following is the most appropriate
action to take regarding resuming anticoagulation?','{"A":"Start the patient on LMVH.","B":"Start the patient on unfractionated heparin.","C":"Resume warfarin.","D":"Resume warfarin and start LMWH.","E":"Resume warfarin after one week."}','D','For patients whose warfarin therapy has been stopped before major surgical procedures, it is recommended that the previous maintenance dose of warfarin be resumed on the night of surgery (12-24 hours) and prophylactic dose of LMWH started at
the same time.
Unfractionated heparin (UFH) can substitute LMWH as a second-line option. Unlike LMWH, UFH use requires monitoring to a target APTT of 1.5 times the normal.
If unfractionated heparin (UFH) is used bolus injection should be avoided and slow infusion used. LMWH or UFH is continued for at least 5 days and is ceased 48 after the target INR is reached (≥1.8).
The reason for co-administration of LMWH or UFH is the fact that warfarin initially increases the risk of thromboembolism.','{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","supporting_pages":[],"source_qid":"1063","duplicate_group_id":"exact-7adfd212adef","duplicate_sources":[{"record_id":"d4a58b6359fbd2cd0cc0","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":622,"source_qid":"1063"}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"strict_ocr_tolerant","text_method":"native","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','high','{"record_id":"d4a58b6359fbd2cd0cc0","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_year":2023,"source_page":622,"source_qid":"1063","domain_hint":"Mixed/Unclassified","stem":"A 65-year-old woman underwent an emergency surgery for a strangulated femoral hernia 2 days ago. She was on warfarin that was ceased before the surgery and fresh frozen plasma was given. Which one of the following is the most appropriate\naction to take regarding resuming anticoagulation?","options":{"A":"Start the patient on LMVH.","B":"Start the patient on unfractionated heparin.","C":"Resume warfarin.","D":"Resume warfarin and start LMWH.","E":"Resume warfarin after one week."},"source_answer":"D","source_explanation":"For patients whose warfarin therapy has been stopped before major surgical procedures, it is recommended that the previous maintenance dose of warfarin be resumed on the night of surgery (12-24 hours) and prophylactic dose of LMWH started at\nthe same time.\nUnfractionated heparin (UFH) can substitute LMWH as a second-line option. Unlike LMWH, UFH use requires monitoring to a target APTT of 1.5 times the normal.\nIf unfractionated heparin (UFH) is used bolus injection should be avoided and slow infusion used. LMWH or UFH is continued for at least 5 days and is ceased 48 after the target INR is reached (≥1.8).\nThe reason for co-administration of LMWH or UFH is the fact that warfarin initially increases the risk of thromboembolism.","source_answer_status":"present","current_answer":null,"current_answer_status":"needs_verification","current_evidence":[],"currentness_risk":"high","currentness_keywords":["anticoag","dose","prophyl","therapy","warfarin"],"likely_visual_question":false,"parser_confidence":"very_high","parser_mode":"strict_ocr_tolerant","text_method":"native","parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","stem_hash":"7adfd212adefb7d44236359c36c3911789dc1977","duplicate_group_id":"exact-7adfd212adef","duplicate_sources":[{"record_id":"d4a58b6359fbd2cd0cc0","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":622,"source_qid":"1063"}]}',1,'v2.9.4','2026-09-24T00:00:00.000Z') ON CONFLICT(record_id) DO UPDATE SET source_file=excluded.source_file,source_page=excluded.source_page,domain=excluded.domain,stem=excluded.stem,options_json=excluded.options_json,source_answer=excluded.source_answer,source_explanation=excluded.source_explanation,provenance_json=excluded.provenance_json,visual_asset=excluded.visual_asset,visual_url=excluded.visual_url,options_mode=excluded.options_mode,current_answer=excluded.current_answer,current_answer_status=excluded.current_answer_status,current_evidence_json=excluded.current_evidence_json,currentness_risk=excluded.currentness_risk,record_json=excluded.record_json,active_quiz=excluded.active_quiz,import_version=excluded.import_version,imported_at=excluded.imported_at;
