sted in the following table:\n \nFactors that may DECREASE skin reaction and give false-negative results\nInfections:\nViral e.g. HIV, measles, mumps, chickenpox, etc\nBacterial e.g. pertussis, brucellosis, leprosy, etc\nFungal\nLive virus vaccination e.g. measles, mumps, polio, etc\nMetabolic diseases e.g. chronic renal failure\nMalnutrition/ protein depletion\nLymphoid neoplasms e.g. Hodgkin’s disease, lymphoma, CML","source_answer_status":"present","current_answer":null,"current_answer_status":"needs_verification","current_evidence":[],"currentness_risk":"high","currentness_keywords":["age","drug","duration","management","therapy","treatment","vaccin"],"likely_visual_question":true,"parser_confidence":"high","parser_mode":"strict_ocr_tolerant","text_method":"native","parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","stem_hash":"be2c62d411b1f7e52ba4a7d12b793e3a5d01747a","duplicate_group_id":"exact-be2c62d411b1","duplicate_sources":[{"record_id":"b88a588da586e181879c","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":647,"source_qid":null}]}',1,'v2.9.4','2026-09-24T00:00:00.000Z') ON CONFLICT(record_id) DO UPDATE SET source_file=excluded.source_file,source_page=excluded.source_page,domain=excluded.domain,stem=excluded.stem,options_json=excluded.options_json,source_answer=excluded.source_answer,source_explanation=excluded.source_explanation,provenance_json=excluded.provenance_json,visual_asset=excluded.visual_asset,visual_url=excluded.visual_url,options_mode=excluded.options_mode,current_answer=excluded.current_answer,current_answer_status=excluded.current_answer_status,current_evidence_json=excluded.current_evidence_json,currentness_risk=excluded.currentness_risk,record_json=excluded.record_json,active_quiz=excluded.active_quiz,import_version=excluded.import_version,imported_at=excluded.imported_at;
