INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('02a574870461e7bafc73','Amedex 2023.pdf','650','Mixed/Unclassified','A 47-year-old woman presents to your practice with complaints of fever, cough and hemoptysis. She is a nurse working in a rural area and has smoked 15 cigarettes a day for the past 20 years. She also has lost eight kg in the past three months. Her
physical examination is unremarkable. A chest X-ray is obtained and shown in the following photograph. Which one of the following is the most appropriate next step in management?','{"A":"Obtain sputum sample for Gram stain.","B":"Bronchoscopy and lavage.","C":"Obtain sputum sample for Zihel - Neelsen stain.","D":"High-resolution CT scan of the chest.","E":"Start the patient on full-dose four-drug therapy for tuberculosis."}','C','Clinical findings of fever, cough, hemoptysis, and weight loss, in the presence of a lesion seen in the upper lobe of the right lung is highly suggestive of pulmonary tuberculosis (TB). This patient should be considered to have TB unless proven
otherwise. When TB is suspected, the next step will be obtaining three sputum samples for acid-fast (Zihel-Neelsen) bacilli staining and culture.
(Option A) Gram-stain does not show TB bacilli and is not used for diagnosing TB.
(Option B) Bronchoscopy and lavage for obtaining samples are indicated if traditionally-obtained samples are negative but, based on clinical grounds, TB is a likely diagnosis.
(Option D) High resolution CT scan of the chest has no role in diagnosis of TB and is not indicated unless the diagnosis is not certain or other diagnoses than TB are considered..
(Option E) Starting the patient on full-dose 4-drug therapy for tuberculosis is indicated in this patient due to high possibility of TB as the diagnosis, but it should be delayed until samples are taken because antibiotics, if used prior to testing, may alter
test results, mostly in form of false negativity.','{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","supporting_pages":[],"source_qid":"362","duplicate_group_id":"exact-bb678f88df29","duplicate_sources":[{"record_id":"02a574870461e7bafc73","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":650,"source_qid":"362"}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"strict_ocr_tolerant","text_method":"native","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','high','{"record_id":"02a574870461e7bafc73","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_year":2023,"source_page":650,"source_qid":"362","domain_hint":"Mixed/Unclassified","stem":"A 47-year-old woman presents to your practice with complaints of fever, cough and hemoptysis. She is a nurse working in a rural area and has smoked 15 cigarettes a day for the past 20 years. She also has lost eight kg in the past three months. Her\nphysical examination is unremarkable. A chest X-ray is obtained and shown in the following photograph. Which one of the following is the most appropriate next step in management?","options":{"A":"Obtain sputum sample for Gram stain.","B":"Bronchoscopy and lavage.","C":"Obtain sputum sample for Zihel - Neelsen stain.","D":"High-resolution CT scan of the chest.","E":"Start the patient on full-dose four-drug therapy for tuberculosis."},"source_answer":"C","source_explanation":"Clinical findings of fever, cough, hemoptysis, and weight loss, in the presence of a lesion seen in the upper lobe of the right lung is highly suggestive of pulmonary tuberculosis (TB). This patient should be considered to have TB unless proven\notherwise. When TB is suspected, the next step will be obtaining three sputum samples for acid-fast (Zihel-Neelsen) bacilli staining and culture.\n(Option A) Gram-stain does not show TB bacilli and is not used for diagnosing TB.\n(Option B) Bronchoscopy and lavage for obtaining samples are indicated if traditionally-obtained samples are negative but, based on clinical grounds, TB is a likely diagnosis.\n(Option D) High resolution CT scan of the chest has no role in diagnosis of TB and is not indicated unless the diagnosis is not certain or other diagnoses than TB are considered..\n(Option E) Starting the patient on full-dose 4-drug therapy for tuberculosis is indicated in this patient due to high possibility of TB as the diagnosis, but it should be delayed until samples are taken because antibiotics, if used prior to testing, may alter\ntest results, mostly in form of false negativity.","source_answer_status":"present","current_answer":null,"current_answer_status":"needs_verification","current_evidence":[],"currentness_risk":"high","currentness_keywords":["age","antibiotic","dose","drug","management","therapy"],"likely_visual_question":true,"parser_confidence":"very_high","parser_mode":"strict_ocr_tolerant","text_method":"native","parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","stem_hash":"bb678f88df2955c1574162b9c505566ce6e09b91","duplicate_group_id":"exact-bb678f88df29","duplicate_sources":[{"record_id":"02a574870461e7bafc73","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":650,"source_qid":"362"}]}',1,'v2.9.4','2026-09-24T00:00:00.000Z') ON CONFLICT(record_id) DO UPDATE SET source_file=excluded.source_file,source_page=excluded.source_page,domain=excluded.domain,stem=excluded.stem,options_json=excluded.options_json,source_answer=excluded.source_answer,source_explanation=excluded.source_explanation,provenance_json=excluded.provenance_json,visual_asset=excluded.visual_asset,visual_url=excluded.visual_url,options_mode=excluded.options_mode,current_answer=excluded.current_answer,current_answer_status=excluded.current_answer_status,current_evidence_json=excluded.current_evidence_json,currentness_risk=excluded.currentness_risk,record_json=excluded.record_json,active_quiz=excluded.active_quiz,import_version=excluded.import_version,imported_at=excluded.imported_at;
