INSERT INTO questions (id,source_id,source_question_no,source_page,domain,system,topic,clinical_task,stem_en,stem_zh,answer_key,source_explanation_en,source_explanation_zh,memory_rule_en,memory_rule_zh,image_ref,source_year,import_version,active,options_mode,provenance_json,current_answer,current_answer_status,current_evidence_json,currentness_risk) VALUES ('02a574870461e7bafc73','src-v294-687f312c','362','650','Mixed/Unclassified','Mixed/Unclassified','Mixed/Unclassified','AMC MCQ','A 47-year-old woman presents to your practice with complaints of fever, cough and hemoptysis. She is a nurse working in a rural area and has smoked 15 cigarettes a day for the past 20 years. She also has lost eight kg in the past three months. Her
physical examination is unremarkable. A chest X-ray is obtained and shown in the following photograph. Which one of the following is the most appropriate next step in management?',NULL,'C','Clinical findings of fever, cough, hemoptysis, and weight loss, in the presence of a lesion seen in the upper lobe of the right lung is highly suggestive of pulmonary tuberculosis (TB). This patient should be considered to have TB unless proven
otherwise. When TB is suspected, the next step will be obtaining three sputum samples for acid-fast (Zihel-Neelsen) bacilli staining and culture.
(Option A) Gram-stain does not show TB bacilli and is not used for diagnosing TB.
(Option B) Bronchoscopy and lavage for obtaining samples are indicated if traditionally-obtained samples are negative but, based on clinical grounds, TB is a likely diagnosis.
(Option D) High resolution CT scan of the chest has no role in diagnosis of TB and is not indicated unless the diagnosis is not certain or other diagnoses than TB are considered..
(Option E) Starting the patient on full-dose 4-drug therapy for tuberculosis is indicated in this patient due to high possibility of TB as the diagnosis, but it should be delayed until samples are taken because antibiotics, if used prior to testing, may alter
test results, mostly in form of false negativity.',NULL,'Retain the source-era answer for question-bank study; verify current Australian guidance before clinical use.',NULL,NULL,'2023','v2.9.4',1,'text','{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","supporting_pages":[],"source_qid":"362","duplicate_group_id":"exact-bb678f88df29","duplicate_sources":[{"record_id":"02a574870461e7bafc73","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":650,"source_qid":"362"}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"strict_ocr_tolerant","text_method":"native","visual_asset":null,"asset_preview_url":null}',NULL,'needs_verification','[]','high') ON CONFLICT(id) DO UPDATE SET source_id=excluded.source_id,source_question_no=excluded.source_question_no,source_page=excluded.source_page,domain=excluded.domain,system=excluded.system,topic=excluded.topic,clinical_task=excluded.clinical_task,stem_en=excluded.stem_en,answer_key=excluded.answer_key,source_explanation_en=excluded.source_explanation_en,memory_rule_en=excluded.memory_rule_en,image_ref=excluded.image_ref,source_year=excluded.source_year,import_version=excluded.import_version,active=1,options_mode=excluded.options_mode,provenance_json=excluded.provenance_json,current_answer=excluded.current_answer,current_answer_status=excluded.current_answer_status,current_evidence_json=excluded.current_evidence_json,currentness_risk=excluded.currentness_risk;
