ent_answer_status":"needs_verification","current_evidence":[],"currentness_risk":"high","currentness_keywords":["age","drug","management","therapy","treatment"],"likely_visual_question":true,"parser_confidence":"high","parser_mode":"strict_ocr_tolerant","text_method":"native","parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","stem_hash":"6ca1fdea727f81031df69aa65d78365d09375092","duplicate_group_id":"exact-6ca1fdea727f","duplicate_sources":[{"record_id":"8b326c6d47692433fe7a","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":682,"source_qid":null}]}',1,'v2.9.4','2026-09-24T00:00:00.000Z') ON CONFLICT(record_id) DO UPDATE SET source_file=excluded.source_file,source_page=excluded.source_page,domain=excluded.domain,stem=excluded.stem,options_json=excluded.options_json,source_answer=excluded.source_answer,source_explanation=excluded.source_explanation,provenance_json=excluded.provenance_json,visual_asset=excluded.visual_asset,visual_url=excluded.visual_url,options_mode=excluded.options_mode,current_answer=excluded.current_answer,current_answer_status=excluded.current_answer_status,current_evidence_json=excluded.current_evidence_json,currentness_risk=excluded.currentness_risk,record_json=excluded.record_json,active_quiz=excluded.active_quiz,import_version=excluded.import_version,imported_at=excluded.imported_at;
