INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('1fc8d739e38083a2eb9e','Amedex 2023.pdf','699','Mixed/Unclassified','A 25-year-old male patient comes to the Emergency Department (ED) complaining of a 3-day history of productive cough, colds, and fever. On further probing, you find that the patient has no other comorbidities and does not have any pertinent travel
history. Vital signs of the patient show a heart rate of 125, respiratory rate of 32, BP of 130/80 mmHg, and O2 saturation of 90% on room air. Physical exam findings indicate bilateral crackles on all lung fields, and the patient speaks only in short
phrases. You arrange for a workup showing the chest x-ray (CXR) as illustrated below and find that the patient is positive for COVID-19 on reverse transcription polymerase chain reaction. Which of the following is the most important in the
management of severe COVID-19?','{"A":"Dexamethasone.","B":"Barcitinib.","C":"Remdesivir.","D":"Azithromycin.","E":"Enoxaparin."}','A','COVID-19 severity is classified according to the following criteria:
Mild:
Adults not presenting any clinical features suggestive of moderate or severe disease or a complicated course of illness.
Characteristics:
No symptoms, or 
mild upper respiratory tract symptoms, or
cough, new myalgia, or asthenia without new shortness of breath or a reduction in oxygen saturation
Moderate:
Stable adult patients presenting with respiratory and/or systemic symptoms or signs. Able to maintain oxygen saturation above 92% (or above 90% for patients with chronic lung disease) with up to 4 L/min oxygen via nasal prongs.
Characteristics:
prostration
severe asthenia
fever > 38 ̊C or persistent cough
clinical or radiological signs of lung involvement
no clinical or laboratory indicators of clinical severity or respiratory impairment
Severe:
Characteristics:
Any one of the following:
Respiratory rate ≥ 30 breaths/min
Oxygen saturation ≤ 92% at a rest state
The arterial partial pressure of oxygen (PaO2)/ inspired oxygen fraction (FiO2) ≤ 300
Critical:','{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","supporting_pages":[],"source_qid":null,"duplicate_group_id":"exact-ba72502ef563","duplicate_sources":[{"record_id":"1fc8d739e38083a2eb9e","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":699,"source_qid":null}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"strict_ocr_tolerant","text_method":"native","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','medium','{"record_id":"1fc8d739e38083a2eb9e","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_year":2023,"source_page":699,"source_qid":null,"domain_hint":"Mixed/Unclassified","stem":"A 25-year-old male patient comes to the Emergency Department (ED) complaining of a 3-day history of productive cough, colds, and fever. On further probing, you find that the patient has no other comorbidities and does not have any pertinent travel\nhistory. Vital signs of the patient show a heart rate of 125, respiratory rate of 32, BP of 130/80 mmHg, and O2 saturation of 90% on room air. Physical exam findings indicate bilateral crackles on all lung fields, and the patient speaks only in short\nphrases. You arrange for a workup showing the chest x-ray (CXR) as illustrated below and find that the patient is positive for COVID-19 on reverse transcription polymerase chain reaction. Which of the following is the most important in the\nmanagement of severe COVID-19?","options":{"A":"Dexamethasone.","B":"Barcitinib.","C":"Remdesivir.","D":"Azithromycin.","E":"Enoxaparin."},"source_answer":"A","source_explanation":"COVID-19 severity is classified according to the following criteria:\nMild:\nAdults not presenting any clinical features suggestive of moderate or severe disease or a complicated course of illness.\nCharacteristics:\nNo symptoms, or \nmild upper respiratory tract symptoms, or\ncough, new myalgia, or asthenia without new shortness of breath or a reduction in oxygen saturation\nModerate:\nStable adult patients presenting with respiratory and/or systemic symptoms or signs. Able to maintain oxygen saturation above 92% (or above 90% for patients with chronic lung disease) with up to 4 L/min oxygen via nasal prongs.\nCharacteristics:\nprostration\nsevere asthenia\nfever > 38 ̊C or persistent cough\nclinical or radiological signs of lung involvement\nno clinical or laboratory indicators of clinical severity or respiratory impairment\nSevere:\nCharacteristics:\nAny one of the following:\nRespiratory rate ≥ 30 breaths/min\nOxygen saturation ≤ 92% at a rest state\nThe arterial partial pressure of oxygen (PaO2)/ inspired oxygen fraction (FiO2) ≤ 300\nCritical:","source_answer_status":"present","current_answer":null,"current_answer_status":"needs_verification","current_evidence":[],"currentness_risk":"medium","currentness_keywords":["age","management"],"likely_visual_question":true,"parser_confidence":"high","parser_mode":"strict_ocr_tolerant","text_method":"native","parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","stem_hash":"ba72502ef5635f6b5d929c58898fb7bca0ff53e1","duplicate_group_id":"exact-ba72502ef563","duplicate_sources":[{"record_id":"1fc8d739e38083a2eb9e","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":699,"source_qid":null}]}',1,'v2.9.4','2026-09-24T00:00:00.000Z') ON CONFLICT(record_id) DO UPDATE SET source_file=excluded.source_file,source_page=excluded.source_page,domain=excluded.domain,stem=excluded.stem,options_json=excluded.options_json,source_answer=excluded.source_answer,source_explanation=excluded.source_explanation,provenance_json=excluded.provenance_json,visual_asset=excluded.visual_asset,visual_url=excluded.visual_url,options_mode=excluded.options_mode,cur