INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('c7d9e5ac45277a10266f','Amedex 2023.pdf','722','Mixed/Unclassified','A 22-year-old college student presents to your practice, complaining of recurrent episodes of drowsiness and feeling detached from the surrounding environment, mostly when she is in a shopping mall. Which one of the following would be the next
best step in management?','{"A":"CT scan of the head.","B":"EEG.","C":"Ask a witness about the episodes.","D":"Polysomnography.","E":"Advise relaxation techniques."}','C','This patient has presented with episodes of transient alteration or absence of consciousness. Evaluation of such episodes is critical to diagnose epileptic seizures, parasomnias, organic enecphalopathies, psychogenic nonepileptic seizure, or
sometimes a false account of the events for malingering.
A witness is a valuable source of information regarding the episode(s), and should be asked about the event if possible. The following are examples of questions to ask:
What did they see?
Did the person become pale or confused before or during the attack?
What does she/he looked like during the attack?
How long does the episode last?
How long did it take before consciousness returned to normal?
A thorough history in conjunction with an account of the event from a witness (if present) is always the very first step in stable patients who present with such episodes.
(Options A, B and D) Investigations such as CT scan, EEG, or polysomnography can be selected for further evaluation of possible diagnoses based on history and physical exam findings.
(Option E) Relaxation techniques are indicated if anxiety is found to be the underlying etiology.','{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","supporting_pages":[],"source_qid":"981","duplicate_group_id":"exact-1a552c41e3ba","duplicate_sources":[{"record_id":"c7d9e5ac45277a10266f","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":722,"source_qid":"981"}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"strict_ocr_tolerant","text_method":"native","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','medium','{"record_id":"c7d9e5ac45277a10266f","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_year":2023,"source_page":722,"source_qid":"981","domain_hint":"Mixed/Unclassified","stem":"A 22-year-old college student presents to your practice, complaining of recurrent episodes of drowsiness and feeling detached from the surrounding environment, mostly when she is in a shopping mall. Which one of the following would be the next\nbest step in management?","options":{"A":"CT scan of the head.","B":"EEG.","C":"Ask a witness about the episodes.","D":"Polysomnography.","E":"Advise relaxation techniques."},"source_answer":"C","source_explanation":"This patient has presented with episodes of transient alteration or absence of consciousness. Evaluation of such episodes is critical to diagnose epileptic seizures, parasomnias, organic enecphalopathies, psychogenic nonepileptic seizure, or\nsometimes a false account of the events for malingering.\nA witness is a valuable source of information regarding the episode(s), and should be asked about the event if possible. The following are examples of questions to ask:\nWhat did they see?\nDid the person become pale or confused before or during the attack?\nWhat does she/he looked lik