INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('10363a04076f25ac8300','Amedex 2023.pdf','758','Mixed/Unclassified','A 68-year-old man presents with a history of headache for the past several months. The headache is worse on waking up, coughing, sneezing and bending forward. He also mentions that he has been suffering from cough for the past 3 months. His
history is significant for smoking of 45 cigarettes a day for the past 45 years. Significant finding on examination is left hemiparesis. A chest X-ray reveals an opacity of 3x2 cm in size in the left lung field. A contrast CT scan of the head is obtained
which is shown in the following picture. Which one of the following could be the most likely diagnosis?','{"A":"Primary brain tumor.","B":"Metastatic brain tumor.","C":"Brain abscess.","D":"Cerebral hemorrhage.","E":"Ischemic stroke."}','B','The clinical picture of headache worse in the morning, and by sneezing, coughing and bending forward is suggestive of a space-occupying lesion in the brain that can be either a tumor or abscess. Considering the age of the patient, history of heavy
smoking and the cough, this patient has lung cancer with high certainty.
Lung cancer is one of the three primary cancers that tend to metastasize to the brain (21%). The other two are melanomas (40%) and breast cancer (9%).
With this history and chest X-ray findings, the lesion is most likely to be a metastatic brain lesion from a primary lung cancer.
Metastatic brain tumors are the most common form of brain tumors. Of all brain tumors, more than a half are metastatic. In patients with systemic malignancies, brain metastases occur in 10-30% of adults and 6-10% of children.
(Option A) With the high probability of an underlying lung cancer in this patient, this tumor is more likely to be metastatic than primary.
(Option C) Brain abscess has similar appearance on contrast CT scan (ring enhancement); however, with absence of fever and considering the history, a brain abscess is not a likely diagnosis.
(Options D and E) The appearance of the lesion as well as the insidious onset and progression of the symptoms make cerebral hemorrhage and ischemic stroke unlikely diagnoses.','{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","supporting_pages":[],"source_qid":"621","duplicate_group_id":"exact-3be7d49bd702","duplicate_sources":[{"record_id":"10363a04076f25ac8300","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":758,"source_qid":"621"}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"strict_ocr_tolerant","text_method":"native","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','medium','{"record_id":"10363a04076f25ac8300","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_year":2023,"source_page":758,"source_qid":"621","domain_hint":"Mixed/Unclassified","stem":"A 68-year-old man presents with a history of headache for the past several months. The headache is worse on waking up, coughing, sneezing and bending forward. He also mentions that he has been suffering from cough for the past 3 months. His\nhistory is significant for smoking of 45 cigarettes a day for the past 45 years. Significant finding on examination is left hemiparesis. A chest X-ray reveals an opacity of 3x2 cm in size in the left lung field. A contrast CT scan of the head is obtained\nwhich is shown in the following picture. Which one of the following could be the most likely diagnosis?","options":{"A":"Primary brain tumor.","B":"Metastatic brain tumor.","C":"Brain abscess.","D":"Cerebral hemorrhage.","E":"Ischemic stroke."},"source_answer":"B","source_explanation":"The clinical picture of headache worse in the morning, and by sneezing, coughing and bending forward is suggestive of a space-occupying lesion in the brain that can be either a tumor or abscess. Considering the age of the patient, history of heavy\nsmoking and the cough, this patient has lung cancer with high certainty.\nLung cancer is one of the three primary cancers that tend to metastasize to the brain (21%). The other two are melanomas (40%) and breast cancer (9%).\nWith this history and chest X-ray findings, the lesion is most likely to be a metastatic brain lesion from a primary lung cancer.\nMetastatic brain tumors are the most common form of brain tumors. Of all brain tumors, more than a half are metastatic. In patients with systemic malignancies, brain metastases occur in 10-30% of adults and 6-10% of children.\n(Option A) With the high probability of an underlying lung cancer in this patient, this tumor is more likely to be metastatic than primary.\n(Option C) Brain abscess has similar appearance on contrast CT scan (ring enhancement); however, with absence of fever and considering the history, a brain abscess is not a likely diagnosis.\n(Options D and E) The appearance of the lesion as well as the insidious onset and progression of the symptoms make cerebral hemorrhage and ischemic stroke unlikely diagnoses.","source_answer_status":"present","current_answer":null,"current_answer_status":"needs_verification","current_evidence":[],"currentness_risk":"medium","currentness_keywords":["age"],"likely_visual_question":true,"parser_confidence":"very_high","parser_mode":"strict_ocr_tolerant","text_method":"native","parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","stem_hash":"3be7d49bd702efc905fe17c98f77916aa71f5c64","duplicate_group_id":"exact-3be7d49bd702","duplicate_sources":[{"record_id":"10363a04076f25ac8300","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":758,"source_qid":"621"}]}',1,'v2.9.4','2026-09-24T00:00:00.000Z') ON CONFLICT(record_id) DO UPDATE SET source_file=excluded.source_file,source_page=excluded.source_page,domain=excluded.domain,stem=excluded.stem,options_json=excluded.options_json,source_answer=excluded.source_answer,source_explanation=excluded.source_explanation,provenance_json=excluded.provenance_json,visual_asset=excluded.visual_asset,visual_url=excluded.visual_url,options_mode=excluded.options_mode,current_answer=excluded.current_answer,current_answer_status=excluded.current_answer_status,current_evidence_json=excluded.current_evidence_json,currentness_risk=excluded.currentness_risk,record_json=excluded.record_json,active_quiz=excluded.active_quiz,import_version=excluded.import_version,imported_at=excluded.imported_at;
