INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('45641e159d4bfc7ba927','Amedex 2023.pdf','768','Mixed/Unclassified','Which one of the following nerves supplies the interosseous muscles of the hand?','{"A":"Radial nerve.","B":"Median nerve.","C":"Ulnar nerve.","D":"Anterior interosseous nerve.","E":"Posterior interosseous nerve."}','C','Interosseous muscles are intrinsic hand muscles that abduct (dorsal interosseous muscles) and adduct (palmar interosseous muscles) the fingers. These muscles are innervated by deep branch of the ulnar nerve.','{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","supporting_pages":[],"source_qid":null,"duplicate_group_id":"exact-bd26290f1b02","duplicate_sources":[{"record_id":"45641e159d4bfc7ba927","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":768,"source_qid":null}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"strict_ocr_tolerant","text_method":"native","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','low','{"record_id":"45641e159d4bfc7ba927","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_year":2023,"source_page":768,"source_qid":null,"domain_hint":"Mixed/Unclassified","stem":"Which one of the following nerves supplies the interosseous muscles of the hand?","options":{"A":"Radial nerve.","B":"Median nerve.","C":"Ulnar nerve.","D":"Anterior interosseous nerve.","E":"Posterior interosseous nerve."},"source_answer":"C","source_explanation":"Interosseous muscles are intrinsic hand muscles that abduct (dorsal interosse