INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('81782cae00bedfaa847a','Amedex 2023.pdf','801','Mixed/Unclassified','A 71-year-old man is brought the Emergency Department with right-sided weakness of his arm and leg. His past medical history is significant for myocardial infarction 3 years ago for which he takes aspirin 100 mg daily. Non-contrast brain CT scan
excludes intracranial hemorrhage. Doppler ultrasonography shows bilateral carotid artery stenosis of 50%. Which one of the following would be the most appropriate initial management?','{"A":"Add warfarin.","B":"Add clopidogrel.","C":"Carotid endarterectomy.","D":"Continue the same dose of aspirin.","E":"Increase the dose of aspirin."}','B','Current guidelines recommend immediate antiplatelet therapy for patients with stroke or TIA after intracranial hemorrhage is excluded using a non-contrast brain CT scan. Aspirin plus clopidogrel should be commenced within 24 hours and continued
short-term. There is strong recommendation against dual therapy with aspirin and clopidogrel for long-term prevention of stroke/ TIA. This patient has developed a stroke while on aspirin. For him, short-term addition of clopidogrel is the most
appropriate immediate step to consider.
It is recommended that asymptomatic patients with carotid artery stenosis of equal to greater than 60% and symptomatic patients with stenosis of equal to or greater than 50% undergo carotid endarterectomy (option C) in an attempt to prevent
further strokes. With a cerebrovascular event and a stenosis of 50% this patent requires carotid endarterectomy, ideally within 2 weeks, as the most appropriate action to prevent further strokes. The question however asks about immediate rather
than long-term management.
(Option A) Warfarin is the preferred anticoagulant to prevent stroke in the setting of atrial fibrillation.
(Option D) With the stenotic carotid artery, continuing the same dose of aspirin is necessary but will not prevent further cerebrovascular events.
(Option E) Increasing the dose of aspirin has not proven effective in prevention of further strokes/TIAs compared to lower doses.','{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","supporting_pages":[],"source_qid":"1678","duplicate_group_id":"exact-ed195b5270e3","duplicate_sources":[{"record_id":"81782cae00bedfaa847a","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":801,"source_qid":"1678"}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"strict_ocr_tolerant","text_method":"native","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','high','{"record_id":"81782cae00bedfaa847a","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_year":2023,"source_page":801,"source_qid":"1678","domain_hint":"Mixed/Unclassified","stem":"A 71-year-old man is brought the Emergency Department with right-sided weakness of his arm and leg. His past medical history is significant for myocardial infarction 3 years ago for which he takes aspirin 100 mg daily. Non-contrast brain CT scan\nexcludes intracranial hemorrhage. Doppler ultrasonography shows bilateral carotid artery stenosis of 50%. Which one of the following would be the most appropriate initial management?","options":{"A":"Add warfarin.","B":"Add clopidogrel.","C":"Carotid endarterectomy.","D":"Continue the same dose of aspirin.","E":"Increase the dose of aspirin."},"source_answer":"B","source_explanation":"Current guidelines recommend immediate antiplatelet therapy for patients with stroke or TIA after intracranial hemorrhage is excluded using a non-contrast brain CT scan. Aspirin plus clopidogrel should be commenced within 24 hours and continued\nshort-term. There is strong recommendation against dual therapy with aspirin and clopidogrel for long-term prevention of stroke/ TIA. This patient has developed a stroke while on aspirin. For him, short-term addition of clopidogrel is the most\nappropriate immediate step to consider.\nIt is recommended that asymptomatic patients with carotid artery stenosis of equal to greater than 60% and symptomatic patients with stenosis of equal to or greater than 50% undergo carotid endarterectomy (option C) in an attempt to prevent\nfurther strokes. With a cerebrovascular event and a stenosis of 50% this patent requires carotid endarterectomy, ideally within 2 weeks, as the most appropriate action to prevent further strokes. The question however asks about immediate rather\nthan long-term management.\n(Option A) Warfarin is the preferred anticoagulant to prevent stroke in the setting of atrial fibrillation.\n(Option D) With the stenotic carotid artery, continuing the same dose of aspirin is necessary but will not prevent further cerebrovascular events.\n(Option E) Increasing the dose of aspirin has not proven effective in prevention of further strokes/TIAs compared to lower doses.","source_answer_status":"present","current_answer":null,"current_answer_status":"needs_verification","current_evidence":[],"currentness_risk":"high","currentness_keywords":["age","anticoag","antiplatelet","dose","guideline","management","therapy","warfarin"],"likely_visual_question":false,"parser_confidence":"very_high","parser_mode":"strict_ocr_tolerant","text_method":"native","parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","stem_hash":"ed195b5270e3e736706049c9d2ded403618846d8","duplicate_group_id":"exact-ed195b5270e3","duplicate_sources":[{"record_id":"81782cae00bedfaa847a","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":801,"source_qid":"1678"}]}',1,'v2.9.4','2026-09-24T00:00:00.000Z') ON CONFLICT(record_id) DO UPDATE SET source_file=excluded.source_file,source_page=excluded.source_page,domain=excluded.domain,stem=excluded.stem,options_json=excluded.options_json,source_answer=excluded.source_answer,source_explanation=excluded.source_explanation,provenance_json=excluded.provenance_json,visual_asset=excluded.visual_asset,visual_url=excluded.visual_url,options_mode=excluded.options_mode,current_answer=excluded.current_answer,current_answer_status=excluded.current_answer_status,current_evidence_json=excluded.current_evidence_json,currentness_risk=excluded.currentness_risk,record_json=excluded.record_json,active_quiz=excluded.active_quiz,import_version=excluded.import_version,imported_at=excluded.imported_at;
