INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('97623e0ad13bc9cb9678','Amedex 2023.pdf','804','Mixed/Unclassified','A 71-year-old man presents to the Emergency Department with weakness of the left arm and leg. His past medical history is significant for coronary angioplasty 5 years ago for which he is currently on daily low-dose aspirin. A non-contrast brain CT
scan excludes cerebral hemorrhage. Doppler ultrasonography shows bilateral carotid artery stenosis of 50%. Which one of the following would be the most appropriate action to takef or long-term secondary prevention?','{"A":"Add warfarin.","B":"Add clopidogrel.","C":"Carotid endarterectomy.","D":"Continue the same dose of aspirin.","E":"Increase the dose of aspirin."}','C','It is recommended that asymptomatic patients with carotid artery stenosis of equal to or greater than 60% and symptomatic patients with stenosis of equal to or greater than 50% undergo endarterectomy in an attempt to prevent further strokes as
the most appropriate management. With a cerebrovascular event and a stenosis of 50% this patent requires carotid endarterectomy as the most appropriate action to prevent further strokes.
(Option A) Warfarin is the preferred anticoagulant to prevent stroke in the setting of atrial fibrillation. 
(Option B) Although short-term combination theray with aspirin and clopidogrel for 3 weeks is recommended for initial pharmacological treatment of patients with stroke or high-risk TIA, long-term use is discouraged and should be avoided unless
they are indicated for acute coronary syndrome or coronary artery stents. If an individual has a stroke while on aspirin, dipyridamole should be added to aspirin or aspirin be switched to clopidogrel. 
(Option D) With the stenotic carotid artery, continuing the same dose of aspirin is necessary but will not prevent further cerebrovascular events.
(Option E) Increasing the dose of aspirin has not proven effective in prevention of further strokes/TIAs compared to lower doses.','{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","supporting_pages":[],"source_qid":"732","duplicate_group_id":"exact-e1a350ef1176","duplicate_sources":[{"record_id":"97623e0ad13bc9cb9678","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":804,"source_qid":"732"}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"strict_ocr_tolerant","text_method":"native","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','high','{"record_id":"97623e0ad13bc9cb9678","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_year":2023,"source_page":804,"source_qid":"732","domain_hint":"Mixed/Unclassified","stem":"A 71-year-old man presents to the Emergency Department with weakness of the left arm and leg. His past medical history is significant for coronary angioplasty 5 years ago for which he is currently on daily low-dose aspirin. A non-contrast brain CT\nscan excludes cerebral hemorrhage. Doppler ultrasonography shows bilateral carotid artery stenosis of 50%. Which one of the following would be the most appropriate action to takef or long-term secondary prevention?","options":{"A":"Add warfarin.","B":"Add clopidogrel.","C":"Carotid endarterectomy.","D":"Continue the same dose of aspirin.","E":"Increase the dose of aspirin."},"source_answer":"C","source_explanation":"It is recommended that asymptomatic patients with carotid artery stenosis of equal to or greater than 60% and symptomatic patients with stenosis of equal to or greater than 50% undergo endarterectomy in an attempt to prevent further strokes as\nthe most appropriate management. With a cerebrovascular event and a stenosis of 50% this patent requires carotid endarterectomy as the most appropriate action to prevent further strokes.\n(Option A) Warfarin is the preferred anticoagulant to prevent stroke in the setting of atrial fibrillation. \n(Option B) Although short-term combination theray with aspirin and clopidogrel for 3 weeks is recommended for initial pharmacological treatment of patients with stroke or high-risk TIA, long-term use is discouraged and should be avoided unless\nthey are indicated for acute coronary syndrome or coronary artery stents. If an individual has a stroke while on aspirin, dipyridamole should be added to aspirin or aspirin be switched to clopidogrel. \n(Option D) With the stenotic carotid artery, continuing the same dose of aspirin is necessary but will not prevent further cerebrovascular events.\n(Option E) Increasing the dose of aspirin has not proven effective in prevention of further strokes/TIAs compared to lower doses.","source_answer_status":"present","current_answer":null,"current_answer_status":"needs_verification","current_evidence":[],"currentness_risk":"high","currentness_keywords":["age","anticoag","dose","management","treatment","warfarin"],"likely_visual_question":false,"parser_confidence":"very_high","parser_mode":"strict_ocr_tolerant","text_method":"native","parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","stem_hash":"e1a350ef117681e01fb8773965733516dad54d5b","duplicate_group_id":"exact-e1a350ef1176","duplicate_sources":[{"record_id":"97623e0ad13bc9cb9678","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":804,"source_qid":"732"}]}',1,'v2.9.4','2026-09-24T00:00:00.000Z') ON CONFLICT(record_id) DO UPDATE SET source_file=excluded.source_file,source_page=excluded.source_page,domain=excluded.domain,stem=excluded.stem,options_json=excluded.options_json,source_answer=excluded.source_answer,source_explanation=excluded.source_explanation,provenance_json=excluded.prov