INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('bd714a4c87752466472b','Amedex 2023.pdf','806','Mixed/Unclassified','A 34-year-old Aboriginal woman is found to be IgM positive, but IgG negative after exposure to a child with rubella during the first trimester of pregnancy. Rubella infection is confirmed with repeated serology testing showing not only a positive IgM,
but also rising titers of IgG. Which one of the following would be the most appropriate next step in management?','{"A":"Termination of the pregnancy.","B":"Give natural human immunoglobulin (NHIG).","C":"Check rubella serology again and get the test reported from another laboratory.","D":"No action is required.","E":"Give MMR vaccine."}','A','The positive IgM for rubella indicates active rubella infection. In such cases, repeating the test is indicated. If IgM is still poitive, diagnosis of rubella infection is confirmed. No further testing from another laboratory (option C) is required.
If rubella infection occurs in the first trimester of pregnancy, the risk of fetal infection and damage is high (85% in the first 2 months of pregnancy, and 50 -80% in the third month); therefore, termination of pregnancy is usually recommended.
NHIG (option B) has been used in trials for prophylaxis and prevention of congenital rubella syndrome after contact to a case with rubella infection. The results have been discouranging; therefor, it is not advised for prophylaxis. This woman, on the
other hand, has establsihed infection and NHIG wil not be of benefit as primary prevention. 
(Option E) Rubella-containing vaccines are contraindicated throughout pregnancy and shoud be avoided. Women who remain susceptible to rubella should receive MMR vaccine postpartum.MMR vaccine is a live attenuate vaccine and is
contraindicated during pregnancy.
OBSTETRICS & GYN','{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","supporting_pages":[],"source_qid":null,"duplicate_group_id":"exact-edce2fda6a6f","duplicate_sources":[{"record_id":"bd714a4c87752466472b","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":806,"source_qid":null}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"strict_ocr_tolerant","text_method":"native","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','high','{"record_id":"bd714a4c87752466472b","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_year":2023,"source_page":806,"source_qid":null,"domain_hint":"Mixed/Unclassified","stem":"A 34-year-old Aboriginal woman is found to be IgM positive, but IgG negative after exposure to a child with rubella during the first trimester of pregnancy. Rubella infection is confirmed with repeated serology testing showing not only a positive IgM,\nbut also rising titers of IgG. Which one of the following would be the most appropriate next step in management?","options":{"A":"Termination of the pregnancy.","B":"Give natural human immunoglobulin (NHIG).","C":"Check rubella serology again and get the test reported from another laboratory.","D":"No action is required.","E":"Give MMR vaccine."},"source_answer":"A","source_explanation":"The positive IgM for rubella indicates active rubella infection. In such cases, repeating the test is indicated. If IgM is still poitive, diagnosis of rubella infection is confirmed. No further testing from another laboratory (option C) is required.\nIf rubella infection occurs in the first trimester of pregnancy, the risk of fetal infection and damage is high (85% in the first 2 months of pregnancy, and 50 -80% in the third month); therefore, termination of pregnancy is usually recommended.\nNHIG (option B) has been used in trials for prophylaxis and prevention of congenital rubella syndrome after contact to a case with rubella infection. The results have been discouranging; therefor, it is not advised for prophylaxis. This woman, on the\nother hand, has establsihed infection and NHIG wil not be of benefit as primary prevention. \n(Option E) Rubella-containing vaccines are contraindicated throughout pregnancy and shoud be avoided. Women who remain susceptible to rubella should receive MMR vaccine postpartum.MMR vaccine is a live attenuate vaccine and is\ncontraindicated during pregnancy.\nOBSTETRICS & GYN","source_answer_status":"present","current_answer":null,"current_answer_status":"needs_verification","current_evidence":[],"currentness_risk":"high","currentness_keywords":["age","management","pregnan","prophyl","vaccin"],"likely_visual_question":false,"parser_confidence":"high","parser_mode":"strict_ocr_tolerant","text_method":"native","parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","stem_hash":"edce2fda6a6fc3eb99966980b8ca86f31fe70ee8","duplicate_group_id":"exact-edce2fda6a6f","duplicate_sources":[{"record_id":"bd714a4c87752466472b","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":806,"source_qid":null}]}',1,'v2.9.4','2026-09-24T00:00:00.000Z') ON CONFLICT(record_id) DO UPDATE SET source_file=excluded.source_file,source_page=excluded.source_page,domain=excluded.domain,stem=excluded.stem,options_json=excluded.options_json,source_answer=excluded.source_answer,source_explanation=excluded.source_explanation,provenance_json=excluded.provenance_json,visual_asset=excluded.visual_asset,visual_url=excluded.visual_url,options_mode=excluded.options_mode,current_answer=excluded.current_answer,current_answer_status=excluded.current_answer_status,current_evidence_json=excluded.current_evidence_json,currentness_risk=excluded.currentness_risk,rec