INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('923efe817e72d2fc42b3','Amedex 2023.pdf','807','Mixed/Unclassified','A 52-year-old lady presents to your GP clinic for breast cancer screening. She has been on combined hormone replacement therapy (HRT) for the past year. Mammogram is the only available method of screening for breast cancer and because of
HRT she is expected to have dense breast tissue. Which one of the following is the best recommendation to this patient regarding HRT and breast cancer screening?','{"A":"Stop HRT six months before mammography.","B":"Stop HRT 1one year before mammography.","C":"Continue HRT and perform mammography as recommended for other women.","D":"Change combined HRT to estrogen-only hormone replacement therapy.","E":"Decrease the dose of combined hormone replacement therapy."}','C','About 10% of women on combined HRT will have extremely dense breasts; nonetheless, presently, there is not enough evidence to recommend that patients on combined hormone replacement therapy should stop HRT for any length of time before
their mammography in an attempt to reduce breast density. Therefore, this patient should continue HRT and have mammography based on current recommendations for other women.
Women making decisions as to whether to commence combined HRT should be aware of the fact that HRT may lead to inaccurate mammography results. Furthermore, they should be informed about the increased risk of breast cancer if HRT
extends beyond the recommended period (3 to 5 years).','{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","supporting_pages":[],"source_qid":null,"duplicate_group_id":"exact-197a4d0a5069","duplicate_sources":[{"record_id":"923efe817e72d2fc42b3","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":807,"source_qid":null}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"strict_ocr_tolerant","text_method":"native","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','high','{"record_id":"923efe817e72d2fc42b3","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_year":2023,"source_page":807,"source_qid":null,"domain_hint":"Mixed/Unclassified","stem":"A 52-year-old lady presents to your GP clinic for breast cancer screening. She has been on combined hormone replacement therapy (HRT) for the past year. Mammogram is the only available method of screening for breast cancer and because of\nHRT she is expected to have dense breast tissue. Which one of the following is the best recommendation to this patient regarding HRT and breast cancer screening?","options":{"A":"Stop HRT six months before mammography.","B":"Stop HRT 1one year before mammography.","C":"Continue HRT and perform mammography as recommended for other women.","D":"Change combined HRT to estrogen-only hormone replacement therapy.","E":"Decrease the dose of combined hormone replacement therapy."},"source_answer":"C","source_explanation":"About 10% of women on combined HRT will have extremely dense breasts; nonetheless, presently, there is not enough evidence to recommend that patients on combined hormone replacement therapy should stop HRT for any length of time before\ntheir mammography in an attempt to reduce breast density. Therefore, this patient should continue HRT 