INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('717d3ae9c4ebd36ec969','Amedex 2023.pdf','808','Mixed/Unclassified','A 34-year-old multigravida, whose fetus is known to be in breech position, presents to the hospital for vaginal delivery. After spontaneous rupture of the membranes, you notice bradycardia and variable deceleration on fetal heart rate monitoring.
Vaginal examination confirms cord prolapse; however the cord is still pulsating. Which one of the following would be the most appropriate next step in management?','{"A":"Push the presenting part away, push the cord up as far as possible, and keep it back with digital pressure.","B":"Continue the vaginal delivery.","C":"Give oxytocin to enhance contractions.","D":"Prophylactic antibiotics.","E":"Fetal scalp blood sampling."}','A','Cord prolapse presents with abnormalities in fetal heart rate patterns (bradycardia, variable decelerations, etc.). If these changes begin after the rupture of the membranes, either spontaneously or with amniotomy, cord prolapse should be strongly
suspected.
Umbilical cord prolapse is abnormal position of the cord in front of the fetal presenting part, resulting in cord compression during labor and fetal hypoxemia.
Once the diagnosis of the cord prolapse is confirmed on pelvic examination and the cord is still pulsating (indicating the fetus is still alive), the presenting part should be pushed up with the examiner''s finger, followed by pushing the cord up as far as
possible and maintaining the digital pressure. 
The mother should be placed in knee-chest position and with the examiners hand in place and \rushed to the operating room for emergency cesarean delivery.
With the child being unstable and severely hypoxemic (reflected by variable decelerations on heart rate monitoring) there is no place for vaginal delivery and emergency cesarean section should be performed.','{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","supporting_pages":[],"source_qid":"436","duplicate_group_id":"exact-e35f3ecaaf64","duplicate_sources":[{"record_id":"717d3ae9c4ebd36ec969","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":808,"source_qid":"436"}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"strict_ocr_tolerant","text_method":"native","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','medium','{"record_id":"717d3ae9c4ebd36ec969","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_year":2023,"source_page":808,"source_qid":"436","domain_hint":"Mixed/Unclassified","stem":"A 34-year-old multigravida, whose fetus is known to be in breech position, presents to the hospital for vaginal delivery. After spontaneous rupture of the membranes, you notice bradycardia and variable deceleration on fetal heart rate monitoring.\nVaginal examination confirms cord prolapse; however the cord is still pulsating. Which one of the following would be the most appropriate next step in management?","options":{"A":"Push the presenting part away, push the cord up as far as possible, and keep it back with digital pressure.","B":"Continue the vaginal delivery.","C":"Give oxytocin to enhance contractions.","D":"Prophylactic antibiotics.","E":"Fetal scalp blood sampling."},"source_answer":"A","source_explanation":"Cord prolapse presents with abnormalities in fetal heart rate patterns (bradycardia, variable decelerations, etc.). If these changes begin after the rupture of the membranes, either spontaneously or with amniotomy, cord prolapse should be strongly\nsuspected.\nUmbilical cord prolapse is abnormal position of the cord in front of the fetal presenting part, resulting in cord compression during labor and fetal hypoxemia.\nOnce the diagnosis of the cord prolapse is confirmed on pelvic examination and the cord is still pulsating (indicating the fetus is still alive), the presenting part should be pushed up with the examiner''s finger, followed by pushing the cord up as far as\npossible and maintaining the digital pressure. \nThe mother should be placed in knee-chest position and with the examiners hand in place and \\rushed to the operating room for emergency cesarean delivery.\nWith the child being unstable and severely hypoxemic (reflected by variable decelerations on heart rate monitoring) there is no place for vaginal delivery and emergency cesarean section should be performed.","source_answer_status":"present","current_answer":null,"current_answer_status":"needs_verification","current_evidence":[],"currentness_risk":"medium","currentness_keywords":["age","management"],"likely_visual_question":false,"parser_confidence":"very_high","parser_mode":"strict_ocr_tolerant","text_method":"native","parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","stem_hash":"e35f3ecaaf645afabbd318cdaf6084ac72fdbb3f","duplicate_group_id":"exact-e35f3ecaaf64","duplicate_sources":[{"record_id":"717d3ae9c4ebd36ec969","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":808,"source_qid":"436"}]}',1,'v2.9.4','2026-09-24T00:00:00.000Z') ON CONFLICT(record_id) DO UPDATE SET source_file=excluded.source_file,source_page=excluded.source_page,domain=excluded.domain,stem=excluded.stem,options_json=excluded.options_json,source_answer=excluded.source_answer,source_explanation=excluded.source_explanation,provenance_json=excluded.provenance_json,visual_asset=excluded.visual_asset,visual_url=excluded.visual_url